//! 单场景语义高亮后端: 供文本预处理生成的脚本, 以及文档代码块等任意场景文本复用
//! WebGAL 高亮 (前端不重复实现任何高亮规则)。

use lsp_types::{Position, Range, SemanticToken};
use webgal_language_core::sentence::Scene;
use webgal_language_service::{
    encode::{highlights_utf8_to_utf16, range_utf16_to_utf8},
    service::{highlight, highlight_range, token_types},
};

/// 语义 token 类型图例 (与 Monaco 语义高亮 provider 的 legend 对应)。
#[tauri::command]
pub fn semantic_token_types() -> Vec<String> {
    token_types()
        .iter()
        .map(|t| t.as_str().to_string())
        .collect()
}

/// 渲染整篇文本 (整个场景) 的高亮。
///
/// 与 [`highlight_scene`] 传整篇区间等价, 但调用方不必自己算末行末列。
/// 返回格式同 [`highlight_scene`].
#[tauri::command]
pub fn highlight_scene_all(text: String) -> Vec<u32> {
    let scene = Scene::from_str(text.as_str());
    let mut tokens = highlight(&scene);
    highlights_utf8_to_utf16(&scene, &mut tokens);

    flatten(tokens)
}

/// 渲染单场景指定区间的高亮。
///
/// 区间为 UTF-16 行列 (与 Monaco 一致), 返回扁平化的
/// `[delta_line, delta_start, length, token_type, token_modifiers_bitset]`
/// 数组, 偏移已转换为 UTF-16 (匹配 Monaco 列号)。
/// 传入整篇区间即为全文高亮 (与 [`highlight_scene_all`] 等价): 末行不按 `end_character` 截断。
#[tauri::command]
pub fn highlight_scene(
    text: String,
    start_line: u32,
    start_character: u32,
    end_line: u32,
    end_character: u32,
) -> Vec<u32> {
    let scene = Scene::from_str(text.as_str());
    let span = range_utf16_to_utf8(
        &scene,
        Range {
            start: Position {
                line: start_line,
                character: start_character,
            },
            end: Position {
                line: end_line,
                character: end_character,
            },
        },
    );
    let mut tokens = highlight_range(&scene, span);
    highlights_utf8_to_utf16(&scene, &mut tokens);

    flatten(tokens)
}

/// 扁平化为 LSP `SemanticTokens.data` 的布局。
fn flatten(tokens: Vec<SemanticToken>) -> Vec<u32> {
    tokens
        .into_iter()
        .flat_map(|token| {
            [
                token.delta_line,
                token.delta_start,
                token.length,
                token.token_type,
                token.token_modifiers_bitset,
            ]
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    /// `highlight_scene_all` 直接返回整篇文本的扁平化 `SemanticTokens.data`
    /// (前端代码块高亮转译用的就是它)。
    #[test]
    fn highlight_scene_all_returns_flat_semantic_tokens() {
        assert_eq!(
            highlight_scene_all("wait:456;".to_string()),
            vec![
                0, 0, 4, 5, 0, // function `wait`
                0, 4, 1, 11, 0, // operator `:`
                0, 1, 3, 9, 0, // number `456`
                0, 3, 1, 7, 0, // comment `;`
                0, 1, 0, 7, 0, // 行尾零长度注释
            ]
        );
    }
}
